## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
Tests ability to blend topological ordering with DP to compute the longest-path in a weighted DAG and count the number of critical paths, including multiple sources and modulo arithmetic.

## Key Concepts
- Longest-path in DAG with node durations and edge setup weights
- Topological sort (Kahn) to process in dependency order
- DP for counting number of longest paths with modulo

## Code Example
```javascript
function countCriticalPaths(N, edges, dur) {
  const MOD = 1000000007;
  const incoming = Array.from({length: N}, () => []);
  const indeg = Array(N).fill(0);

  for (const [u, v, w] of edges) {
    incoming[v].push([u, w]);
    indeg[v]++;
  }

  const EFT = dur.slice();
  const count = Array(N).fill(0);
  const q = [];

  for (let i = 0; i < N; i++) {
    if (indeg[i] === 0) {
      count[i] = 1;
      q.push(i);
    }
  }

  while (q.length) {
    const u = q.shift();
    for (const [v, w] of incoming[u]) {
      const newEFT = EFT[u] + w + dur[v];
      if (newEFT > EFT[v]) {
        EFT[v] = newEFT;
        count[v] = count[u];
      } else if (newEFT === EFT[v]) {
        count[v] = (count[v] + count[u]) % MOD;
      }
      indeg[u]--;
      if (indeg[u] === 0) q.push(u);
    }
  }

  let maxEFT = 0, totalCritical = 0;
  for (let i = 0; i < N; i++) {
    if (EFT[i] > maxEFT) {
      maxEFT = EFT[i];
      totalCritical = count[i];
    } else if (EFT[i] === maxEFT) {
      totalCritical = (totalCritical + count[i]) % MOD;
    }
  }
  return { EFT, maxEFT, criticalPaths: totalCritical };
}
```

## Complexity
- Time: O(N + M) for topological sort and DP
- Space: O(N + M) for adjacency and arrays

## Why This Is Asked

Tests practical graph DP with a real-world flavor (service startup), ensuring knowledge of cycle detection, topological order, and dynamic programming.

## Key Concepts

- Topological sort (Kahn/DFS)
- DAG DP for path/finish times
- Cycle detection via processed node count

## Code Example

```javascript
function earliestStartup(graph, startup, t) {
  const V = graph.length;
  const indeg = new Array(V).fill(0);
  for (let u = 0; u < V; u++) for (const v of graph[u]) indeg[v]++;
  const q = [];
  const earliest = startup.slice();
  for (let i = 0; i < V; i++) if (indeg[i] === 0) q.push(i);
  let seen = 0;
  while (q.length) {
    const u = q.shift();
    seen++;
    for (const v of graph[u]) {
      earliest[v] = Math.max(earliest[v], earliest[u] + startup[v]);
      if (--indeg[v] === 0) q.push(v);
    }
  }
  if (seen !== V) throw new Error('cycle detected');
  return earliest[t];
}
```

